const kind=document.body.dataset.concept;
const titles={money:['01 · MONEY','货币，让交换变得简单','货币是被广泛接受的支付手段。今天的钱不仅是纸币和硬币，也包括银行账户中的存款。'],rates:['02 · INTEREST RATE','利率，是使用资金的价格','借款人支付利息以提前使用资金；储蓄者获得利息以推迟使用资金。利率连接今天与未来。'],inflation:['03 · INFLATION','通胀，让同样的钱买得更少','通货膨胀是总体价格水平持续上涨。它描述的是一篮子商品和服务的变化，而不是某一件商品偶尔涨价。']};
const node=(a,b,c='')=>`<div class="node"><span class="icon">${c}</span><strong>${a}</strong><small>${b}</small></div>`;
const flow=(...n)=>`<div class="flow">${n.join('<span class="arrow" aria-hidden="true">→</span>')}</div>`;
const chapter=(id,title,desc,content)=>`<section class="chapter"><div class="eyebrow">${id}</div><h2>${title}</h2><p class="caption">${desc}</p>${content}</section>`;
const card=(h,p,i)=>`<article class="card"><span class="icon">${i}</span><h3>${h}</h3><p>${p}</p></article>`;
const content={
money:chapter('01 · 交换的桥梁','没有货币，每笔交易都要刚好匹配','想象你有面包，想换一双鞋。但鞋匠想要的可能是牛奶。货币把两次交换拆开，让每个人可以自由选择交易对象。',`<div class="stage">${flow(node('卖出面包','面包师获得货币','♧'),node('获得货币','统一的交换媒介','¥'),node('购买鞋子','不必找到双向需求','◇'))}</div><div class="cols" style="margin-top:20px">${card('交换媒介','用钱换取商品和服务，降低交易成本。','⇄')}${card('计价单位','用统一的尺度比较面包、鞋子与劳动的价格。','≡')}${card('价值储藏','把今天的购买力留到未来，但会受到通胀影响。','◷')}</div>`)+
chapter('02 · 存款货币','银行贷款时，存款也会被创造','商业银行发放贷款，通常会同时在借款人的账户中记入一笔存款。这是资产负债表上的同步变化，并非凭空增加社会净财富。',`<div class="stage"><div class="tabs"><button class="active" data-credit="0">发放前</button><button data-credit="1">发放贷款</button><button data-credit="2">偿还本金</button></div><div class="ledger"><div>银行资产 · 对客户的贷款<b id="loan">¥0</b></div><div>银行负债 · 客户的存款<b id="deposit">¥0</b></div></div><p id="creditExplain" class="caption">点击“发放贷款”，看银行的资产与负债如何同时变化。</p></div><div class="note">贷款受到资本、流动性、监管和借款人资质约束。银行不能无限制创造存款；央行货币与商业银行存款也不是同一种负债。</div>`)+
chapter('03 · 循环流动','你的支出，是另一个人的收入','货币在经济活动中不断转手。居民提供劳动、领取收入，消费又成为企业的收入。',`<div class="stage dark">${flow(node('居民','提供劳动、购买商品','○'),node('企业','支付工资、生产商品','▥'),node('居民','工资收入再次进入消费','↻'))}<p class="caption">这是一段循环：居民 → 消费支出 → 企业 → 工资与分配 → 居民。税收、储蓄和对外贸易也会影响资金流向。</p></div>`),
rates:chapter('01 · 利率传导','拖动利率，观察行为方向','在其他条件相近时，利率上升通常抬高融资成本、抑制需求。下图只演示方向，条形长度不是现实预测。',`<div class="stage dark"><div class="control"><label for="rate">示意年利率</label><output id="rateValue" class="number">3.0%</output></div><input id="rate" type="range" min="0" max="8" step="0.1" value="3"><div class="bars"><div class="bar-row"><span>借款意愿</span><div class="track"><div id="borrow" class="fill"></div></div><b id="borrowLabel"></b></div><div class="bar-row"><span>储蓄吸引力</span><div class="track"><div id="saving" class="fill"></div></div><b id="savingLabel"></b></div></div><p class="caption">现实中的反应还取决于收入预期、债务结构和银行是否愿意放贷。</p></div><div class="stage">${flow(node('政策利率上升','影响市场资金成本','↑'),node('融资成本上升','新贷款更贵','¥'),node('总需求降温','消费与扩张趋缓','↘'))}<p class="caption">需求降温可能缓和通胀，但存在时滞；政策利率、存款利率和个人贷款利率不会完全同步变化。</p></div>`)+
chapter('02 · 生活中的利率','同一笔贷款，每年利息有何变化？','用一笔 10 万元、期限一年的贷款理解利息。这里采用单利、到期还本，不代表分期房贷的月供。',`<div class="stage"><div class="formula"><div><span class="number">100,000</span><small>借款本金 · 元</small></div><span>×</span><div><span class="number" id="costRate">3.0%</span><small>年利率</small></div><span>=</span><div><span class="number" id="cost">3,000</span><small>一年利息 · 元</small></div></div><p class="caption">金额随上方利率控制杆同步变化。固定利率贷款在约定期内通常不会因市场利率变化而直接调整。</p></div>`)+
chapter('03 · 实际利率','数字增长了，购买力也增长了吗？','实际利率需要考虑通胀。直观近似：实际利率 ≈ 名义利率 − 通胀率。更精确的关系为 (1 + 名义利率) ÷ (1 + 通胀率) − 1。',`<div class="stage"><div class="formula"><div><span class="number">4.0%</span><small>名义收益</small></div><span>−</span><div><span class="number">2.5%</span><small>通胀</small></div><span>≈</span><div><span class="number">1.5%</span><small>实际收益</small></div></div><div class="note">如果名义收益为 4%，通胀为 6%，购买力仍可能下降。看利率时，需要同时看价格水平的变化。</div></div>`),
inflation:chapter('01 · 购买力','同样 100 元，还能装满购物篮吗？','假设所有商品以相同速度涨价。拖动年数，观察固定预算的购买力；模型未计收入变化，也不是未来通胀预测。',`<div class="stage"><div class="control"><label for="years">经过的年数 · 假设年通胀 3%</label><output id="yearValue" class="number">10 年</output></div><input id="years" type="range" min="0" max="30" value="10"><div class="ledger"><div>原来 100 元的商品，现在需要<b id="price">¥134.39</b></div><div>现在 100 元，相当于当年的<b id="power">¥74.41</b></div></div><div id="basket" class="basket" aria-label="购买力示意购物篮"></div><p class="caption">每个圆点代表原始购物篮的 10%，淡色部分表示固定预算已无法购买的份额。</p></div>`)+
chapter('02 · 上涨的原因','需求变多，或供给变贵','通胀可能来自不同力量，也可能由多种因素共同推动。切换场景，看价格压力从哪里开始。',`<div class="stage"><div class="tabs"><button class="active" data-cause="demand">需求拉动</button><button data-cause="supply">成本推动</button></div><div id="causeFlow"></div><p id="causeText" class="caption"></p></div><div class="note">货币、信贷与预期也会影响需求和定价，但“货币增加”并不意味着物价立即、等比例上涨，还要看产出、资金使用和经济环境。</div>`)+
chapter('03 · 如何衡量','CPI 看的是一篮子，不是一件商品','消费价格指数以居民消费的一篮子商品与服务为基础，按权重汇总价格变化。不同家庭的消费结构不同，体感通胀也会不同。',`<div class="stage"><div class="ledger"><div style="background:transparent"><div class="ring" role="img" aria-label="示例消费篮子：食品35%，居住30%，交通20%，其他15%"></div></div><div><strong>假设的消费篮子权重</strong><p class="caption">● 食品 35%　● 居住 30%<br>● 交通 20%　● 其他 15%</p><p class="caption">这组比例仅用于解释加权方法，不是任何地区的官方 CPI 权重。</p></div></div></div><div class="cols" style="margin-top:20px">${card('通胀','价格总体仍在上涨，例如从 100 涨到 105。','↗')}${card('通胀放缓','价格还在涨，只是速度从 5% 降到 2%；不等于降价。','⤴')}${card('通缩','价格总体持续下降，可能与需求疲弱和债务压力相伴。','↘')}</div>`)
};
const [en,title,desc]=titles[kind];document.querySelector('#app').innerHTML=`<div class="wrap"><header><a href="financial-basics.html">← 宏观基础</a><nav>${Object.keys(titles).map(k=>`<a class="${kind===k?'active':''}" href="${k}.html">${{money:'货币',rates:'利率',inflation:'通胀'}[k]}</a>`).join('')}</nav></header><main><section class="hero"><div class="eyebrow">${en}</div><h1>${title}</h1><p class="intro">${desc}</p></section>${content[kind]}<div class="next"><a href="financial-basics.html">返回概念地图</a><a href="${{money:'rates',rates:'inflation',inflation:'money'}[kind]}.html">继续探索：${{money:'利率',rates:'通胀',inflation:'货币'}[kind]} →</a></div></main><footer>图形与数字均为简化教学示例，仅用于知识理解。<p class="source">延伸阅读：<a href="https://www.bankofengland.co.uk/explainers/how-is-money-created" target="_blank" rel="noopener">货币创造</a> · <a href="https://www.bankofengland.co.uk/explainers/why-have-interest-rates-in-the-uk-gone-up" target="_blank" rel="noopener">利率传导</a> · <a href="https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/what_is_inflation.en.html" target="_blank" rel="noopener">通胀与价格指数</a></p></footer></div>`;
if(kind==='money')document.querySelectorAll('[data-credit]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-credit]').forEach(x=>x.classList.toggle('active',x===b));const step=+b.dataset.credit;document.querySelector('#loan').textContent=document.querySelector('#deposit').textContent=step===1?'¥10,000':'¥0';document.querySelector('#creditExplain').textContent=['尚未发放贷款：本示例新增贷款与新增存款均为零。','发放 1 万元贷款：银行增加 1 万元贷款资产，同时增加 1 万元存款负债。借款人有存款，也有同额债务。','假设用银行存款偿还全部本金：相应贷款与存款同时减少。利息的会计处理不在本图范围内。'][step]});
if(kind==='rates'){const s=document.querySelector('#rate');const update=()=>{const v=+s.value;document.querySelector('#rateValue').textContent=document.querySelector('#costRate').textContent=v.toFixed(1)+'%';document.querySelector('#cost').textContent=(v*1000).toLocaleString('zh-CN');document.querySelector('#borrow').style.width=(100-v*11)+'%';document.querySelector('#saving').style.width=(12+v*11)+'%';document.querySelector('#borrowLabel').textContent=v<3?'较强':v<6?'中等':'较弱';document.querySelector('#savingLabel').textContent=v<3?'较低':v<6?'中等':'较高'};s.oninput=update;update()}
if(kind==='inflation'){const s=document.querySelector('#years');const update=()=>{const y=+s.value,p=100*Math.pow(1.03,y),power=10000/p;document.querySelector('#yearValue').textContent=y+' 年';document.querySelector('#price').textContent='¥'+p.toFixed(2);document.querySelector('#power').textContent='¥'+power.toFixed(2);document.querySelector('#basket').innerHTML=Array.from({length:10},(_,i)=>`<i style="opacity:${Math.min(1,Math.max(.12,power/10-i))}">●</i>`).join('')};s.oninput=update;update();document.querySelectorAll('[data-cause]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-cause]').forEach(x=>x.classList.toggle('active',x===b));const demand=b.dataset.cause==='demand';document.querySelector('#causeFlow').innerHTML=demand?flow(node('需求增加','更多人愿意购买','↑'),node('供给短期有限','产能来不及跟上','▥'),node('价格承压','竞争同一批商品','↗')):flow(node('生产成本上升','能源、原料更贵','↑'),node('供给承压','生产更贵或减产','▥'),node('价格承压','部分成本向下游传递','↗'));document.querySelector('#causeText').textContent=demand?'例子：消费需求突然增加，但商品数量没有同步增加，商家更容易提高价格。':'例子：能源涨价提高运输与生产成本，即使需求没有增强，商品也可能涨价。'});document.querySelector('[data-cause]').click()}
